#!/bin/sh
# Regenerates the C that zugojson builds from its Goose source.
#
#   tools/regenerate.sh /path/to/goose-checkout            # rewrite src/
#   tools/regenerate.sh --verify /path/to/goose-checkout   # diff only
#
# The checkout must be at the commit in tools/goose/PIN and already built
# (cmake -S . -B build && cmake --build build), so that build/goose exists.
# Nothing here runs at install time: CRAN machines have no Goose compiler,
# so the generated files are committed and shipped.
#
# Writes, from tools/goose/zugojson.goose and the checkout:
#   src/zugojson_goose.c  the compiled program, with no main
#   src/zugojson_goose.h  its exported functions
#   src/goose_version.h   the runtime interface hash the two halves share
#   src/goose_vendor.c    byte search and number formatting, verbatim from
#                         goose's src/runtime/runtime_impl.h
# and records their checksums in tools/goose/PROVENANCE.

set -eu

verify=0
if [ "${1:-}" = "--verify" ]; then
  verify=1
  shift
fi
if [ $# -ne 1 ]; then
  echo "usage: $0 [--verify] <goose-checkout>" >&2
  exit 2
fi

pkg=$(cd "$(dirname "$0")/.." && pwd)
gsrc=$(cd "$1" && pwd)
goose="$gsrc/build/goose"
pin=$(cat "$pkg/tools/goose/PIN")

[ -x "$goose" ] || { echo "no compiler at $goose; build the checkout" >&2; exit 1; }
head=$(git -C "$gsrc" rev-parse HEAD)
if [ "$head" != "$pin" ]; then
  echo "goose checkout is at $head, tools/goose/PIN says $pin" >&2
  exit 1
fi

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT

# The compiler names source files by the path it was given. Run it from
# tools/goose so the package's own file is a bare name.
(cd "$pkg/tools/goose" &&
  "$goose" -o "$out/zugojson_goose.c" --header "$out/zugojson_goose.h" \
    zugojson.goose >/dev/null)

# The standard library is named by its absolute path in the checkout.
# Rewrite it so the output does not depend on where the checkout lives.
sed 's|"[^"]*/stdlib/\([A-Za-z0-9_]*\.goose\)"|"goose/stdlib/\1"|' \
  "$out/zugojson_goose.c" >"$out/tmp.c"
mv "$out/tmp.c" "$out/zugojson_goose.c"

# Local patch: the 128-bit multiply helpers use unsigned __int128, which
# -pedantic reports as "ISO C does not support '__int128' types". R CMD
# check counts any "ISO C" warning as significant, and CRAN's r-devel
# flavors compile with -pedantic. One __extension__ typedef silences it
# without a pragma. The patch must apply exactly once.
n=$(grep -c '^#elif defined(__SIZEOF_INT128__)$' "$out/zugojson_goose.c" || true)
[ "$n" -eq 1 ] || { echo "int128 patch: expected 1 anchor, found $n" >&2; exit 1; }
sed -e 's/unsigned __int128/gs_r_u128/g' \
  -e '/^#elif defined(__SIZEOF_INT128__)$/a\
__extension__ typedef unsigned __int128 gs_r_u128; /* zugojson patch */' \
  "$out/zugojson_goose.c" >"$out/tmp.c"
mv "$out/tmp.c" "$out/zugojson_goose.c"
if grep -q '__int128' "$out/zugojson_goose.c" &&
   [ "$(grep -c '__int128' "$out/zugojson_goose.c")" -ne 1 ]; then
  echo "int128 patch: a use of __int128 is left over" >&2
  exit 1
fi

version=$(sed -n 's/^#define GS_RUNTIME_VERSION \([0-9a-f]*\)$/\1/p' \
  "$out/zugojson_goose.c")
[ -n "$version" ] || { echo "no GS_RUNTIME_VERSION in generated C" >&2; exit 1; }
cat >"$out/goose_version.h" <<EOF
/* Generated by tools/regenerate.sh. The runtime interface hash of the
   Goose compiler at tools/goose/PIN: goose_r_runtime.c defines the
   start-up function under this name, so C generated by another compiler
   version fails to link instead of misbehaving. */
#ifndef GOOSE_VERSION_H
#define GOOSE_VERSION_H
#define GS_RUNTIME_VERSION $version
#endif
EOF

# Runtime pieces copied verbatim from runtime_impl.h, each found by anchor
# lines: byte sets and byte search, on the portable path (GS_SCAN_SSE2
# stays undefined, as on every non-x86 machine), and number formatting.
# The generated C references both, even where -O2 optimises the calls out.
impl="$gsrc/src/runtime/runtime_impl.h"
line_of() {
  n=$(grep -n "$1" "$impl" | head -1 | cut -d: -f1)
  [ -n "$n" ] || { echo "anchor not found in runtime_impl.h: $1" >&2; exit 1; }
  echo "$n"
}
# The first line at or after line $1 that is a "}" in column 0.
close_of() {
  awk -v from="$1" 'NR >= from && /^}/ { print NR; exit }' "$impl"
}
set_first=$(line_of '^#if (defined(__GNUC__) || defined(__clang__)) && !defined(__TINYC__)$')
set_last=$(($(line_of '^#if !defined(__TINYC__) && (defined(__x86_64__) || defined(_M_X64))$') - 1))
scan_first=$(line_of '^GS_API int64_t gs_scan_any(')
scan_last=$(close_of "$(line_of '^GS_API int64_t gs_scan_pair(')")
fmt_first=$(line_of '^static const char gs_digit_pairs')
fmt_last=$(($(line_of '^/\* stdout is unbuffered') - 1))
if [ "$set_first" -ge "$set_last" ] || [ "$scan_first" -ge "$scan_last" ] ||
   [ "$fmt_first" -ge "$fmt_last" ]; then
  echo "runtime_impl.h anchors are out of order" >&2
  exit 1
fi
{
  printf '%s\n' \
    "/* Generated by tools/regenerate.sh: pieces of goose's" \
    "   src/runtime/runtime_impl.h at tools/goose/PIN, verbatim after this" \
    "   header: lines $set_first-$set_last (byte sets), $scan_first-$scan_last (byte search)" \
    "   and $fmt_first-$fmt_last (number formatting). Copyright Wouter van" \
    "   Oortmerssen, Apache-2.0; see inst/licenses/goose-LICENSE. Never edit" \
    "   by hand. */" \
    "#include <math.h>" \
    "#include <stdint.h>" \
    "#include <string.h>" \
    "#define GS_API"
  sed -n "${set_first},${set_last}p" "$impl"
  echo
  sed -n "${scan_first},${scan_last}p" "$impl"
  echo
  sed -n "${fmt_first},${fmt_last}p" "$impl"
} >"$out/goose_vendor.c"

files="zugojson_goose.c zugojson_goose.h goose_version.h goose_vendor.c"

if [ "$verify" -eq 1 ]; then
  status=0
  for f in $files; do
    if ! cmp -s "$out/$f" "$pkg/src/$f"; then
      echo "src/$f differs from what tools/goose and the pin generate" >&2
      status=1
    fi
  done
  [ "$status" -eq 0 ] && echo "generated files match"
  exit "$status"
fi

for f in $files; do cp "$out/$f" "$pkg/src/$f"; done

{
  echo "# Written by tools/regenerate.sh. Do not edit."
  echo "goose_repository https://github.com/aardappel/goose"
  echo "goose_commit $pin"
  echo "runtime_version $version"
  for f in $files; do
    echo "sha256 $(cd "$pkg/src" && sha256sum "$f")"
  done
} >"$pkg/tools/goose/PROVENANCE"

echo "regenerated $files at goose $pin"
